(function() {
var display = document.getElementById('display');
var current = '0';
var justEvaluated = false;
function updateDisplay() {
display.textContent = current;
}
function isOperator(ch) {
return ch === '+' || ch === '-' || ch === '*' || ch === '/';
}
// Safe expression evaluator: no eval / no Function
function safeEvaluate(expr) {
var tokens = [];
var num = '';
for (var i = 0; i < expr.length; i++) {
var c = expr[i];
if ((c >= '0' && c <= '9') || c === '.') {
num += c;
} else if (isOperator(c)) {
if (num === '') {
if (c === '-' && (i === 0 || isOperator(expr[i-1]))) {
num = '-';
continue;
} else {
return 'Error';
}
}
tokens.push(parseFloat(num));
tokens.push(c);
num = '';
} else {
return 'Error';
}
}
if (num === '' || num === '-') return 'Error';
tokens.push(parseFloat(num));
// Handle leading zeros: parseFloat naturally handles them
// First pass: * and /
var reduced = [];
var j = 0;
while (j < tokens.length) {
if (typeof tokens[j] === 'number') {
reduced.push(tokens[j]);
j++;
} else {
var op = tokens[j];
var left = reduced.pop();
var right = tokens[j+1];
if (typeof right !== 'number') return 'Error';
if (op === '*') reduced.push(left * right);
else if (op === '/') {
if (right === 0) return 'Error';
reduced.push(left / right);
}
j += 2;
}
}
// Second pass: + and -
var result = reduced[0];
for (var k = 1; k < reduced.length; k += 2) {
var oper = reduced[k];
var val = reduced[k+1];
if (oper === '+') result += val;
else if (oper === '-') result -= val;
else return 'Error';
}
return result;
}
function handleNum(num) {
if (justEvaluated) {
current = (num === '.') ? '0.' : num;
justEvaluated = false;
updateDisplay();
return;
}
if (num === '.') {
var parts = current.split(/[\+\-\*\/]/);
var last = parts[parts.length - 1];
if (last.indexOf('.') !== -1) return;
if (last === '' || isOperator(current[current.length-1])) current += '0.';
else current += '.';
} else {
if (current === '0') current = num;
else if (isOperator(current[current.length-1])) current += num;
else {
var segs = current.split(/[\+\-\*\/]/);
if (segs[segs.length-1] === '0') {
var idx = current.lastIndexOf('0');
current = current.slice(0, idx) + num + current.slice(idx+1);
} else {
current += num;
}
}
}
updateDisplay();
}
function handleOp(op) {
