if (current === '0' && op !== '-') return;
if (isOperator(current[current.length-1])) {
if (op === '-' && current[current.length-1] !== '-') {
current += op;
} else {
current = current.slice(0, -1) + op;
}
} else {
current += op;
}
updateDisplay();
}
function handleClear() {
current = '0';
justEvaluated = false;
updateDisplay();
}
function handleEquals() {
if (isOperator(current[current.length-1])) return;
var res = safeEvaluate(current);
if (res === 'Error') {
current = 'Error';
} else {
if (!isFinite(res)) current = 'Error';
else current = String(res);
}
justEvaluated = true;
updateDisplay();
}
